Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
using pii = pair<int, int>;

template<typename T, typename U> inline T lower_bound_assign(T& a, const U& b) { if (b < a) a = b; return a; }
template<typename T, typename U> inline T upper_bound_assign(T& a, const U& b) { if (a < b) a = b; return a; }

#define loop(i, a, b) for (int i = (a), _end = (b); i < _end; ++i)
#define repeat(i, n) loop(i, 0, n)

const int MAX_N = 205;
const int MAX_M = MAX_N * MAX_N;
#define prev some

int readInt() { int x; cin >> x; return x; }

int prev_edge[MAX_M], visited[MAX_N], head[MAX_N], src[MAX_M], cap[MAX_M], dst[MAX_M], edge_count = 0;
int A[MAX_N][MAX_N], B[MAX_N][MAX_N], red[MAX_N][MAX_N], blocked[MAX_N][MAX_N];
int dist[MAX_N][MAX_N], counter, dist_red[MAX_N], seen_bfs[MAX_N];
pii queue[MAX_N];
const int dX[4] = {0, -1, 0, 1};
const int dY[4] = {1, 0, -1, 0};

void connect(int u, int v, int uv, int vu) {
	src[edge_count] = u; dst[edge_count] = v; cap[edge_count] = uv; prev_edge[edge_count] = head[u]; head[u] = edge_count++;
	src[edge_count] = v; dst[edge_count] = u; cap[edge_count] = vu; prev_edge[edge_count] = head[v]; head[v] = edge_count++;
}

int augment(int v, int t, int f = 2000000000) {
	if (v == t) return f;
	if (visited[v]++) return 0;
	for (int e = head[v]; ~e; e = prev_edge[e]) if (cap[e]) {
		int u = dst[e];
		int flow = augment(u, t, min(f, cap[e]));
		if (flow) { cap[e] -= flow; cap[e ^ 1] += flow; return flow; }
	}
	return 0;
}

int flow(int s, int t) {
	int total = 0;
	for (;;) {
		memset(visited, 0, sizeof visited);
		int delta = augment(s, t);
		total += delta;
		if (!delta) break;
	}
	return total;
}

int main() {
	ios::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
	int n = readInt(), T = readInt();
	memset(head, -1, sizeof head);
	memset(dist, 63, sizeof dist);
	repeat(i, MAX_N) dist[i][i] = 0;
	repeat(x, n) repeat(y, n) {
		char c; cin >> c;
		if (c == 'Y') blocked[x][y] = 1;
		else if (c == 'Z') red[x][y] = 1;
		else A[x][y] = c - '0';
	}
	repeat(x, n) repeat(y, n) {
		char c; cin >> c;
		if (c != 'Y' && c != 'Z') {
			B[x][y] = c - '0';
			repeat(d, 4) {
				int nx = x + dX[d], ny = y + dY[d];
				if (nx >= 0 && ny >= 0 && nx < n && ny < n && !blocked[nx][ny] && !red[nx][ny])
					dist[x * n + y][nx * n + ny] = 1;
			}
		}
	}
	int N = n * n;
	repeat(k, N) repeat(i, N) repeat(j, N)
		if (dist[i][k] + dist[k][j] < dist[i][j])
			dist[i][j] = dist[i][k] + dist[k][j];
	int qh = 0, qt = 0;
	memset(dist_red, 63, sizeof dist_red);
	repeat(i, n) repeat(j, n)
		if (red[i][j]) {
			queue[qt++] = {i, j};
			dist_red[i * n + j] = 0;
		}
	while (qh != qt) {
		auto cur = queue[qh++];
		int x = cur.first, y = cur.second;
		repeat(d, 4) {
			int nx = x + dX[d], ny = y + dY[d];
			if (nx >= 0 && ny >= 0 && nx < n && ny < n && !blocked[nx][ny] && !red[nx][ny] && dist_red[nx * n + ny] > 1e9) {
				dist_red[nx * n + ny] = dist_red[x * n + y] + 1;
				queue[qt++] = {nx, ny};
			}
		}
	}
	int sink = MAX_N - 1, source = MAX_N - 2;
	repeat(start, N) {
		memset(seen_bfs, 0, sizeof seen_bfs);
		qh = 0; qt = 0;
		int sx = start / n, sy = start % n;
		if (blocked[sx][sy] || red[sx][sy]) continue;
		queue[qt++] = {sx, sy};
		seen_bfs[start] = 1;
		while (qh != qt) {
			int x = queue[qh].first, y = queue[qh++].second;
			if (dist[start][x * n + y] <= T)
				connect(start << 1, (x * n + y) << 1 | 1, 1000, 0);
			if (dist[start][x * n + y] == dist_red[x * n + y]) continue;
			repeat(d, 4) {
				int nx = x + dX[d], ny = y + dY[d], nid = nx * n + ny;
				if (nx >= 0 && ny >= 0 && nx < n && ny < n && !blocked[nx][ny] && !red[nx][ny] && dist[start][nid] <= dist_red[nid] && dist[start][nid] <= T && dist[start][nid] > dist[start][x * n + y] && !seen_bfs[nid]) {
					queue[qt++] = {nx, ny};
					seen_bfs[nid] = 1;
				}
			}
		}
	}
	repeat(i, N) connect(source, i << 1, A[i / n][i % n], 0);
	repeat(i, N) connect((i << 1) | 1, sink, B[i / n][i % n], 0);
	cout << flow(source, sink);
}
